'use strict';
let studioMode='edit',previewDevice='auto',previewOrientation='portrait',selectedPointId=null,pointDragging=false,pendingArrival=null;
const studioHistory=[];
const studioV2=studio,settingsV2=editorSettings,auditV2=audit,validateV2=validateWorkspaceData;
function studioCheckpoint(){const p=project();studioHistory.push({project:p.id,scenes:p.scenes.map(s=>({id:s.id,initialView:structuredClone(s.initialView),hotspots:structuredClone(s.hotspots)})),transition:p.transition,transitionDuration:p.transitionDuration,transitionColor:p.transitionColor,startSceneId:p.startSceneId});if(studioHistory.length>20)studioHistory.shift()}
async function saveStudio(message){project().status='Em edição';try{await save();if(message)toast(message)}catch(e){toast('Não foi possível salvar. Baixe um backup antes de sair.');throw e}}
function refreshStudio(){studio()}
studio=()=>{
 const preserved=viewer?MGExperience.getView(viewer):null;studioV2();if(!project()||!$('#stage'))return;
 $('.badge').textContent='PROTÓTIPO FUNCIONAL · V0.3';const stage=$('#stage');stage.dataset.device=previewDevice;stage.dataset.orientation=previewOrientation;
 const toolbar=document.createElement('div');toolbar.className='preview-tools';toolbar.innerHTML=`<label>Visualização<select id="preview-device"><option value="auto">Adaptar à área</option><option value="desktop">Desktop</option><option value="tablet">Tablet</option><option value="mobile">Mobile · 390 px</option></select></label><button id="preview-orientation" ${previewDevice==='mobile'?'':'disabled'}>${previewOrientation==='portrait'?'▯ Vertical':'▭ Horizontal'}</button><button id="studio-mode" class="${studioMode==='preview'?'active':''}">${studioMode==='edit'?'▶ Testar navegação':'✎ Voltar à edição'}</button><button id="studio-undo" ${studioHistory.at(-1)?.project===project().id?'':'disabled'}>↶ Desfazer edição</button><span class="hint">${studioMode==='edit'?'Arraste um ponto para reposicionar; clique para editar.':'Prévia do visitante: clique nos pontos para navegar.'}</span><small>A prévia muda a área real de renderização. A validação em aparelhos físicos continua necessária.</small>`;
 $('.editor').before(toolbar);$('#preview-device').value=previewDevice;
 bind('preview-device','change',e=>{previewDevice=e.target.value;studio()});bind('preview-orientation','click',()=>{previewOrientation=previewOrientation==='portrait'?'landscape':'portrait';studio()});bind('studio-mode','click',()=>{studioMode=studioMode==='edit'?'preview':'edit';drawPoints();studio()});
 bind('studio-undo','click',async()=>{const old=studioHistory.pop();if(!old||old.project!==project().id)return;for(const prior of old.scenes){const s=project().scenes.find(s=>s.id===prior.id);if(s){s.hotspots=prior.hotspots;s.initialView=prior.initialView}}for(const key of['transition','transitionDuration','transitionColor','startSceneId'])project()[key]=old[key];await saveStudio('Última edição desfeita.');studio()});
 const camera=pendingArrival||preserved||currentScene()?.initialView;pendingArrival=null;if(camera)MGExperience.setView(viewer,camera);
 const home=$('#home-scene');if(home)home.onclick=()=>selectScene(Math.max(0,project().scenes.findIndex(s=>s.id===project().startSceneId)));
 drawPoints();
};
selectScene=(i,point=null)=>{const p=project();if(i<0||!p.scenes[i])return;const snapshot=MGExperience.capture(viewer),viewBefore=viewer?MGExperience.getView(viewer):null,cfg=MGExperience.config(p),custom=point?MGExperience.point(point):null;if(custom?.transition&&custom.transition!=='inherit')cfg.effect=custom.transition;viewer?.destroy();viewer=null;sceneIndex=i;pendingArrival=custom?.arrival||(p.scenes[i].keepDirection?viewBefore:p.scenes[i].initialView)||{yaw:0,pitch:0,fov:80};selectedPointId=null;studio();MGExperience.transition($('#stage'),viewer,snapshot,cfg)};
function runPoint(h){if(h.type==='scene'){const i=project().scenes.findIndex(s=>s.id===h.target);if(i>=0)selectScene(i,h);else toast('O destino deste ponto não existe.')}else if(h.type==='link'){const u=safeURL(h.target);if(u)window.open(u,'_blank','noopener,noreferrer')}else modal(`<h2>${escapeHTML(h.label)}</h2><p style="white-space:pre-wrap">${escapeHTML(h.target)}</p>`)}
drawPoints=()=>{
 const layer=$('#hotspot-layer');if(!layer||!viewer||pointDragging)return;const scene=currentScene();if(!scene)return;
 const ids=new Set(scene.hotspots.map(h=>h.id));for(const child of [...layer.children])if(!ids.has(child.dataset.pointId))child.remove();
 for(const h of scene.hotspots){let b=[...layer.children].find(el=>el.dataset.pointId===h.id);if(!b){b=document.createElement('button');b.className='hotspot';b.dataset.pointId=h.id;b.type='button';layer.append(b);wirePoint(b,h)}const pos=viewer.project(h.yaw,h.pitch);b.hidden=!pos;if(pos){b.style.left=pos.x+'px';b.style.top=pos.y+'px'}b.title=h.label;b.setAttribute('aria-label',`${studioMode==='edit'?'Editar ponto: ':''}${h.label}`);b.dataset.mode=studioMode;b.dataset.selected=String(h.id===selectedPointId);MGExperience.stylePoint(b,h)}
 if($('#camera-live')&&viewer){const v=MGExperience.getView(viewer);$('#camera-live').textContent=`Horizontal ${v.yaw.toFixed(1)}° · Vertical ${v.pitch.toFixed(1)}° · Campo ${v.fov.toFixed(0)}°`}
};
function wirePoint(button,h){
 let drag=null,suppressClick=false;
 button.addEventListener('pointerdown',e=>{if(studioMode!=='edit')return;e.preventDefault();e.stopPropagation();selectedPointId=h.id;pointDragging=true;drag={x:e.clientX,y:e.clientY,moved:false,old:{yaw:h.yaw,pitch:h.pitch}};button.setPointerCapture(e.pointerId);button.dataset.selected='true'});
 button.addEventListener('pointermove',e=>{if(!drag)return;e.stopPropagation();if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<4&&!drag.moved)return;if(!drag.moved){studioCheckpoint();drag.moved=true}const r=viewer.c.getBoundingClientRect(),x=Math.max(0,Math.min(r.width,e.clientX-r.left)),y=Math.max(0,Math.min(r.height,e.clientY-r.top));Object.assign(h,viewer.unproject(x,y));const pos=viewer.project(h.yaw,h.pitch);if(pos){button.style.left=pos.x+'px';button.style.top=pos.y+'px'}});
 const end=async e=>{if(!drag)return;e.stopPropagation();const moved=drag.moved;drag=null;pointDragging=false;suppressClick=moved;if(moved){try{await saveStudio('Posição do ponto salva.');editorSettings()}catch{}}drawPoints()};
 button.addEventListener('pointerup',end);button.addEventListener('pointercancel',e=>{if(drag?.moved)Object.assign(h,drag.old);drag=null;pointDragging=false;drawPoints()});
 button.onclick=e=>{e.stopPropagation();if(suppressClick){suppressClick=false;return}if(studioMode==='edit'){selectedPointId=h.id;pointForm({yaw:h.yaw,pitch:h.pitch},h)}else runPoint(h)};
 button.onkeydown=async e=>{if(studioMode!=='edit'||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();studioCheckpoint();h.yaw=MGExperience.view({yaw:h.yaw+(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0)}).yaw;h.pitch=MGExperience.view({pitch:h.pitch+(e.key==='ArrowUp'?1:e.key==='ArrowDown'?-1:0)}).pitch;await saveStudio();drawPoints()};
}
pointForm=(position,existing=null)=>{
 const scene=currentScene();if(!scene)return;const draft={id:uid(),label:'',type:'scene',target:project().scenes.find(s=>s.id!==scene.id)?.id||'',...position,...(existing||{})},s=MGExperience.point(draft);
 const option=(values,value)=>Object.entries(values).map(([key,label])=>`<option value="${key}" ${key===value?'selected':''}>${label}</option>`).join('');
 modal(`<div class="eyebrow">EDITOR DE PONTO · ${escapeHTML(scene.name)}</div><h2>${existing?'Editar interação':'Novo ponto de interação'}</h2><form id="advanced-point" class="formgrid">${field('Legenda *','ap-label',draft.label,'text','required maxlength="180"')}<label>Ação<select id="ap-type"><option value="scene">Ir para ambiente</option><option value="info">Informação</option><option value="link">Link externo</option></select></label><label class="full" id="ap-scene-wrap">Ambiente de destino<select id="ap-target">${project().scenes.filter(t=>t.id!==scene.id).map(t=>`<option value="${t.id}" ${t.id===draft.target?'selected':''}>${escapeHTML(t.name)}</option>`).join('')}</select></label><label class="full" id="ap-content-wrap">Conteúdo ou endereço HTTP(S)<textarea id="ap-content" maxlength="10000">${escapeHTML(draft.type==='scene'?'':draft.target)}</textarea></label><label>Formato<select id="ap-shape">${option(MGExperience.shapes,s.shape)}</select></label><label>Animação<select id="ap-animation">${option(MGExperience.animations,s.animation)}</select></label>${field('Tamanho · px','ap-size',s.size,'number','min="24" max="96" step="1"')}${field('Rotação · graus','ap-rotation',s.rotation,'number','min="-180" max="180" step="1"')}${field('Opacidade · %','ap-opacity',s.opacity,'number','min="20" max="100"')}${field('Cor do ponto','ap-color',s.color,'color')}${field('Posição horizontal · graus','ap-yaw',draft.yaw,'number','min="-180" max="180" step="any"')}${field('Posição vertical · graus','ap-pitch',draft.pitch,'number','min="-85" max="85" step="any"')}<div class="point-actions full"><button type="button" id="ap-up">↑ Subir 5°</button><button type="button" id="ap-down">↓ Descer 5°</button><button type="button" id="ap-center">Trazer para o centro da vista</button></div><label class="full">Transição deste ponto<select id="ap-transition"><option value="inherit">Usar padrão do projeto</option>${option(MGExperience.effects,s.transition)}</select></label><div class="full arrival-fields"><label><input type="checkbox" id="ap-arrival" ${s.arrival?'checked':''}> Personalizar câmera ao chegar ao destino</label><div class="formgrid">${field('Chegada horizontal · graus','ap-arrival-yaw',s.arrival?.yaw||0,'number','min="-180" max="180" step="any"')}${field('Chegada vertical · graus','ap-arrival-pitch',s.arrival?.pitch||0,'number','min="-85" max="85" step="any"')}${field('Chegada campo de visão · graus','ap-arrival-fov',s.arrival?.fov||80,'number','min="35" max="110"')}</div><p class="hotspot-help">Esses ângulos pertencem à cena de destino. A visão atual do panorama de origem é usada apenas pelo botão de centralização do ponto.</p></div><div class="full actions"><button class="dark" type="submit">Salvar ponto</button><button type="button" id="ap-cancel">Cancelar</button></div></form>`);
 $('#ap-type').value=draft.type;$('#ap-transition').value=s.transition;const sync=()=>{$('#ap-scene-wrap').hidden=$('#ap-type').value!=='scene';$('#ap-content-wrap').hidden=$('#ap-type').value==='scene';$('.arrival-fields').hidden=$('#ap-type').value!=='scene'};sync();bind('ap-type','change',sync);
 bind('ap-center','click',()=>{if(viewer){const v=MGExperience.getView(viewer);$('#ap-yaw').value=v.yaw.toFixed(1);$('#ap-pitch').value=v.pitch.toFixed(1)}});for(const [id,delta]of[['ap-up',5],['ap-down',-5]])bind(id,'click',()=>{$('#ap-pitch').value=Math.max(-85,Math.min(85,+$('#ap-pitch').value+delta))});bind('ap-cancel','click',closeModal);
 bind('advanced-point','submit',async e=>{e.preventDefault();const type=$('#ap-type').value,target=type==='scene'?$('#ap-target').value:$('#ap-content').value.trim(),label=$('#ap-label').value.trim();if(!label||!target||(type==='link'&&!safeURL(target)))return toast('Preencha a legenda e um destino válido.');const out={...draft,label,type,target,yaw:+$('#ap-yaw').value,pitch:+$('#ap-pitch').value,shape:$('#ap-shape').value,animation:$('#ap-animation').value,size:+$('#ap-size').value,rotation:+$('#ap-rotation').value,opacity:+$('#ap-opacity').value,color:$('#ap-color').value,transition:$('#ap-transition').value,arrival:type==='scene'&&$('#ap-arrival').checked?MGExperience.view({yaw:+$('#ap-arrival-yaw').value,pitch:+$('#ap-arrival-pitch').value,fov:+$('#ap-arrival-fov').value}):null};Object.assign(out,MGExperience.point(out));studioCheckpoint();if(existing)Object.assign(existing,out);else scene.hotspots.push(out);selectedPointId=out.id;await saveStudio('Ponto salvo neste projeto.');closeModal();studio()});
};
editorSettings=()=>{
 settingsV2();const p=project(),s=currentScene(),el=$('#editor-settings');if(!p||!el)return;
 if(editorTab==='hotspots'){
 const extra=document.createElement('div');extra.className='view-editor';extra.innerHTML=`<h3>Editar os pontos deste ambiente</h3><p class="hotspot-help">No modo de edição, arraste diretamente no panorama. As setas do teclado movem o ponto focado em 1°. No modo de navegação, o clique executa a ação.</p><div class="point-list">${(s?.hotspots||[]).map(h=>`<button data-edit-point="${h.id}" class="${selectedPointId===h.id?'selected':''}">✎ ${escapeHTML(h.label)}</button><button data-test-point="${h.id}">Testar ação</button>`).join('')||'<p>Nenhum ponto neste ambiente.</p>'}</div>`;el.append(extra);$$('[data-edit-point]').forEach(b=>b.onclick=()=>{const h=s.hotspots.find(h=>h.id===b.dataset.editPoint);selectedPointId=h.id;pointForm({yaw:h.yaw,pitch:h.pitch},h)});$$('[data-test-point]').forEach(b=>b.onclick=()=>runPoint(s.hotspots.find(h=>h.id===b.dataset.testPoint)));
 }
 if(editorTab==='transicoes'){
 const cfg=MGExperience.config(p);el.innerHTML=`<h2>Transições entre ambientes</h2><p>Oito efeitos próprios sobre panoramas. Um ponto pode substituir o padrão do projeto. As animações aguardam o carregamento da cena e respeitam movimento reduzido.</p><div class="transition-grid">${Object.entries(MGExperience.effects).map(([key,name])=>`<button data-transition="${key}" aria-pressed="${cfg.effect===key}">${name}</button>`).join('')}</div><div class="formgrid">${field('Duração · ms','effect-duration',cfg.duration,'number','min="150" max="2000" step="50"')}${field('Cor da passagem','effect-color',cfg.color,'color')}</div><div class="actions" style="margin-top:18px"><button id="save-effect">Salvar ajustes</button><button id="test-effect" ${p.scenes.length<2?'disabled':''}>Testar no próximo ambiente</button></div><p class="editor-settings-caption">O player de prévia e o ZIP usam o mesmo módulo de efeitos. Integração nativa com 3DVista continua pendente.</p>`;
 $$('[data-transition]').forEach(b=>b.onclick=async()=>{studioCheckpoint();p.transition=b.dataset.transition;await saveStudio();editorSettings()});bind('save-effect','click',async()=>{const duration=+$('#effect-duration').value;if(!Number.isFinite(duration)||duration<150||duration>2000)return toast('Use uma duração de 150 a 2000 ms.');studioCheckpoint();p.transitionDuration=duration;p.transitionColor=$('#effect-color').value;await saveStudio('Ajustes da transição salvos.');editorSettings()});bind('test-effect','click',()=>selectScene((sceneIndex+1)%p.scenes.length));
 }
 if(editorTab==='aparencia'&&s){const extra=document.createElement('section');extra.className='view-editor';extra.innerHTML=`<h3>Visão inicial e entrada do tour</h3><p id="camera-live" class="camera-readout"></p><div class="actions"><button id="save-scene-view">Definir visão inicial desta cena</button><button id="test-scene-view">Testar visão inicial</button><button id="save-tour-home">Definir esta cena como entrada</button></div><p class="hotspot-help">A posição e o zoom são salvos na cena. Um hotspot com câmera de chegada própria tem prioridade.</p><label><input type="checkbox" id="keep-view" ${s.keepDirection?'checked':''}> Manter direção da câmera ao entrar nesta cena</label>`;el.append(extra);bind('save-scene-view','click',async()=>{if(!viewer)return;studioCheckpoint();s.initialView=MGExperience.getView(viewer);await saveStudio('Visão inicial da cena salva.');drawPoints()});bind('test-scene-view','click',()=>{MGExperience.setView(viewer,s.initialView||{});drawPoints()});bind('save-tour-home','click',async()=>{studioCheckpoint();p.startSceneId=s.id;await saveStudio('Entrada do tour definida.');});bind('keep-view','change',async e=>{studioCheckpoint();s.keepDirection=e.target.checked;await saveStudio()});drawPoints()}
};
audit=p=>{const result=auditV2(p);const ids=new Set(p.scenes.map(s=>s.id));for(const pin of p.pins||[])if(!ids.has(pin.scene))result.push({level:'erro',text:'Planta: pino aponta para um ambiente inexistente.'});if(p.startSceneId&&!ids.has(p.startSceneId))result.push({level:'erro',text:'A cena de entrada não existe.'});for(const s of p.scenes)for(const h of s.hotspots){if(!Number.isFinite(h.yaw)||!Number.isFinite(h.pitch)||Math.abs(h.pitch)>85||Math.abs(h.yaw)>180)result.push({level:'erro',text:s.name+': posição angular inválida.'});if(h.type==='scene'&&h.target===s.id)result.push({level:'aviso',text:s.name+': ponto retorna ao próprio ambiente.'});}return result};
validateWorkspaceData=data=>{validateV2(data);const finite=(value,min,max)=>typeof value==='number'&&Number.isFinite(value)&&value>=min&&value<=max;const checkView=v=>{if(v&&(!finite(v.yaw,-180,180)||!finite(v.pitch,-85,85)||!finite(v.fov,35,110)))throw Error('Câmera de cena inválida.')};for(const p of data.projects){if(p.transition&&!Object.hasOwn(MGExperience.effects,p.transition))throw Error('Transição desconhecida.');if(p.transitionDuration!==undefined&&!finite(p.transitionDuration,150,2000))throw Error('Duração de transição inválida.');if(p.transitionColor!==undefined&&!/^#[a-f\d]{6}$/i.test(p.transitionColor))throw Error('Cor de transição inválida.');if(p.startSceneId!==undefined&&!p.scenes.some(s=>s.id===p.startSceneId))throw Error('Cena inicial inválida.');for(const s of p.scenes){checkView(s.initialView);for(const h of s.hotspots){if(!finite(h.yaw,-180,180)||!finite(h.pitch,-85,85))throw Error('Posição de ponto inválida.');checkView(h.arrival);for(const [key,min,max]of[['size',24,96],['rotation',-180,180],['opacity',20,100]])if(h[key]!==undefined&&!finite(h[key],min,max))throw Error('Aparência de ponto inválida.');if(h.color&&!/^#[a-f\d]{6}$/i.test(h.color))throw Error('Cor de ponto inválida.');for(const [key,allowed]of[['shape',MGExperience.shapes],['animation',MGExperience.animations],['transition',{inherit:'',...MGExperience.effects}]])if(h[key]!==undefined&&!Object.hasOwn(allowed,h[key]))throw Error('Modelo de ponto inválido.');}}}return data};
